const $=s=>document.querySelector(s), KEY='linkdesk.v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');
const demo=[['Atlas Media','Travel Club','UA','Передана',true],['Northside Agency','Learn Online','PL','Передана',false],['Pulse Partners','Fitness Plus','DE','Получена',false],['Atlas Media','Home & Living','UA','Передана',false],['Orbit Traffic','Language Lab','GB','Остановлена',false],['Nova Digital','City Break','CZ','Получена',true]].map((a,i)=>({id:'demo-'+i,partner:a[0],offer:a[1],geo:a[2],status:a[3],favorite:a[4],url:`https://example.com/offer/${i+1}?partner=demo${i+1}&geo=${a[2].toLowerCase()}`,note:'Демонстрационная запись. Все названия и ссылки вымышлены.',source:i%2?'Закреп в чате · демо':'CRM · демо',sent:a[3]==='Передана'?'2026-10-28':'',updated:'2026-10-28T10:00:00.000Z',history:[],demo:true}));
let records;let storageBroken=false;try{const raw=localStorage.getItem(KEY);records=raw?JSON.parse(raw):structuredClone(demo);if(!Array.isArray(records))throw Error();}catch{records=structuredClone(demo);storageBroken=true;}
let favoriteOnly=false,toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));records=next;render();return true}catch{toast('Не удалось сохранить: проверьте доступное место в браузере.');return false}}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Скопировано в буфер обмена')}catch{toast('Копирование недоступно. Выделите текст в карточке.')}}
function render(){const geos=[...new Set(records.map(r=>r.geo))].sort(), selected=$('#geo').value;$('#geo').innerHTML='<option value="">Все GEO</option>'+geos.map(g=>`<option ${g===selected?'selected':''}>${esc(g)}</option>`).join('');const q=$('#search').value.toLowerCase().trim(),status=$('#status').value,geo=$('#geo').value;const list=records.filter(r=>(!favoriteOnly||r.favorite)&&(!status||r.status===status)&&(!geo||r.geo===geo)&&[r.partner,r.offer,r.url,r.geo,r.note,r.source].join(' ').toLowerCase().includes(q)).sort((a,b)=>b.updated.localeCompare(a.updated));$('#stats').innerHTML=[[records.length,'Всего ссылок','Вся база в одном месте','↗'],[records.filter(r=>r.status==='Передана').length,'Переданы партнёрам','Готовы к работе','✓'],[new Set(records.map(r=>r.partner.toLowerCase())).size,'Партнёров','У каждого своя ссылка','♧'],[geos.length,'GEO в работе','География ваших офферов','◎']].map(a=>`<div class="stat"><div class="label">${a[1]}</div><span class="badge-icon">${a[3]}</span><div class="number">${a[0]}</div><div class="caption">${a[2]}</div></div>`).join('');$('#navCount').textContent=records.length;$('#listTitle').firstChild.textContent=favoriteOnly?'Избранные ссылки ':'Реестр ссылок ';$('#resultCount').textContent=list.length;$('#rows').innerHTML=list.map(r=>`<tr><td><button class="star ${r.favorite?'on':''}" data-action="favorite" data-id="${esc(r.id)}" aria-label="${r.favorite?'Убрать из избранного':'В избранное'}">${r.favorite?'★':'☆'}</button></td><td><button class="offer" data-action="edit" data-id="${esc(r.id)}">${esc(r.offer)}<small>${esc(r.partner)}</small></button></td><td><span class="geo-tag">${esc(r.geo)}</span></td><td><div class="url"><span title="${esc(r.url)}">${esc(r.url)}</span><button class="copy" data-action="copy" data-id="${esc(r.id)}" aria-label="Копировать ссылку">⧉</button></div></td><td><span class="pill ${r.status==='Получена'?'received':r.status==='Передана'?'sent':'stopped'}">${esc(r.status)}</span></td><td>${esc(new Date(r.updated).toLocaleDateString('ru-RU',{day:'2-digit',month:'short'}))}</td><td><button class="more" data-action="edit" data-id="${esc(r.id)}" aria-label="Открыть карточку">↗</button></td></tr>`).join('');$('#empty').hidden=!!list.length;$('#footerCount').textContent=`Показано ${list.length} из ${records.length} ссылок`;$('#clearDemo').hidden=!records.some(r=>r.demo);$('#allNav').classList.toggle('active',!favoriteOnly);$('#starNav').classList.toggle('active',favoriteOnly)}
function openEditor(id){const form=$('#form');form.reset();const r=records.find(r=>r.id===id);for(const key of ['id','partner','offer','geo','url','status','sent','source','note'])form.elements[key].value=r?.[key]??(key==='status'?'Получена':'');$('#modalTitle').textContent=r?'Карточка ссылки':'Новая ссылка';$('#delete').hidden=!r;$('#detailActions').hidden=!r;$('#history').innerHTML=r?.history.length?'<h3>Предыдущие версии ссылки</h3>'+r.history.slice().reverse().map(h=>`<div>${esc(new Date(h.at).toLocaleString('ru-RU'))}<code>${esc(h.url)}</code></div>`).join(''):'';$('#editor').showModal()}
$('#add').onclick=()=>openEditor();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>$('#editor').close());$('#rows').onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const r=records.find(r=>r.id===b.dataset.id);if(!r)return;if(b.dataset.action==='edit')openEditor(r.id);if(b.dataset.action==='copy')copy(r.url);if(b.dataset.action==='favorite')persist(records.map(x=>x.id===r.id?{...x,favorite:!x.favorite}:x))};
$('#form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;const data=Object.fromEntries(new FormData(f));for(const k in data)if(k!=='url')data[k]=data[k].trim();data.url=data.url.trim();let url;try{url=new URL(data.url);if(!['http:','https:'].includes(url.protocol))throw Error()}catch{toast('Укажите ссылку, начинающуюся с https:// или http://');return}if(!data.partner||!data.offer||!data.geo){toast('Заполните партнёра, оффер и GEO');return}const old=records.find(r=>r.id===data.id),at=new Date().toISOString();const history=old?[...old.history]:[];if(old&&old.url!==data.url)history.push({url:old.url,at});const next={...old,...data,id:old?.id||(crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('')),updated:at,history,favorite:old?.favorite||false,demo:false};if(persist(old?records.map(r=>r.id===old.id?next:r):[next,...records])){$('#editor').close();toast('Ссылка сохранена')}};
$('#delete').onclick=()=>{const id=$('#form').elements.id.value;if(confirm('Удалить эту карточку вместе с историей?'))if(persist(records.filter(r=>r.id!==id))){$('#editor').close();toast('Карточка удалена')}};
$('#copyDetail').onclick=()=>copy($('#form').elements.url.value);$('#message').onclick=()=>{const f=$('#form').elements;$('#messageText').value=`Привет! Передаю готовую ссылку.\n\nОффер: ${f.offer.value}\nGEO: ${f.geo.value}\nПартнёр: ${f.partner.value}\n\n${f.url.value}\n\nЕсли возникнут вопросы по подключению — напиши.`;$('#messageDialog').showModal()};$('#closeMessage').onclick=()=>$('#messageDialog').close();$('#copyMessage').onclick=()=>copy($('#messageText').value);
$('#search').oninput=render;$('#geo').onchange=render;$('#status').onchange=render;$('#allNav').onclick=()=>{favoriteOnly=false;render()};$('#starNav').onclick=()=>{favoriteOnly=true;render()};
$('#clearDemo').onclick=()=>{if(confirm('Убрать все демонстрационные записи? Ваши карточки останутся.'))persist(records.filter(r=>!r.demo))};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`link-desk-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия выгружена')};
function validateImport(data){if(data.version!==1||!Array.isArray(data.records)||data.records.length>10000)throw Error();const ids=new Set();return data.records.map(r=>{if(!r||typeof r!=='object')throw Error();for(const k of ['id','partner','offer','geo','url','status','sent','source','note','updated'])if(typeof r[k]!=='string')throw Error();if(!r.id||ids.has(r.id)||!r.partner.trim()||!r.offer.trim()||!r.geo.trim()||!['Получена','Передана','Остановлена'].includes(r.status)||isNaN(Date.parse(r.updated)))throw Error();ids.add(r.id);const u=new URL(r.url);if(!['https:','http:'].includes(u.protocol))throw Error();if(!Array.isArray(r.history)||r.history.some(h=>!h||typeof h.url!=='string'||typeof h.at!=='string'||isNaN(Date.parse(h.at))))throw Error();return {id:r.id,partner:r.partner,offer:r.offer,geo:r.geo,url:r.url,status:r.status,sent:r.sent,source:r.source,note:r.note,updated:r.updated,history:r.history.map(h=>({url:h.url,at:h.at})),favorite:!!r.favorite,demo:!!r.demo}})}
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error();const next=validateImport(JSON.parse(await file.text()));if(confirm(`Импортировать ${next.length} записей? Текущая база будет заменена. Сначала сохраните экспорт, если он нужен.`)){if(persist(next))toast('Резервная копия восстановлена')}}catch{toast('Неверный файл. Выберите экспорт Link Desk (JSON до 10 МБ).')}finally{e.target.value=''}};
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=JSON.parse(e.newValue);if(Array.isArray(next)){records=next;render()}}catch{}}});render();if(storageBroken)toast('Не удалось прочитать базу. Сохраните резервную копию перед работой.');
